--
-- Table structure for table `flight_status_history`
--

DROP TABLE IF EXISTS `flight_status_history`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `flight_status_history` (
  `status_history_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `flight_id` bigint unsigned NOT NULL,
  `status` varchar(30) NOT NULL,
  `status_time` datetime NOT NULL,
  `remarks` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`status_history_id`),
  KEY `idx_status_history_flight` (`flight_id`),
  KEY `idx_status_history_time` (`status_time`),
  CONSTRAINT `fk_status_history_flight` FOREIGN KEY (`flight_id`) REFERENCES `flights` (`flight_id`)
) ENGINE=InnoDB AUTO_INCREMENT=18107 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

