--
-- Table structure for table `flights`
--

DROP TABLE IF EXISTS `flights`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `flights` (
  `flight_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `flight_number` varchar(20) NOT NULL,
  `airline_id` int unsigned NOT NULL,
  `aircraft_id` int unsigned NOT NULL,
  `pilot_id` int unsigned NOT NULL,
  `origin_airport_id` int unsigned NOT NULL,
  `destination_airport_id` int unsigned NOT NULL,
  `gate_id` int unsigned DEFAULT NULL,
  `scheduled_departure` datetime NOT NULL,
  `scheduled_arrival` datetime NOT NULL,
  `actual_departure` datetime DEFAULT NULL,
  `actual_arrival` datetime DEFAULT NULL,
  `status` varchar(30) NOT NULL DEFAULT 'Scheduled',
  `delay_minutes` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`flight_id`),
  KEY `idx_flights_airline` (`airline_id`),
  KEY `idx_flights_aircraft` (`aircraft_id`),
  KEY `idx_flights_pilot` (`pilot_id`),
  KEY `idx_flights_origin` (`origin_airport_id`),
  KEY `idx_flights_destination` (`destination_airport_id`),
  KEY `idx_flights_gate` (`gate_id`),
  KEY `idx_flights_departure` (`scheduled_departure`),
  KEY `idx_flights_status` (`status`),
  CONSTRAINT `fk_flight_aircraft` FOREIGN KEY (`aircraft_id`) REFERENCES `aircraft` (`aircraft_id`),
  CONSTRAINT `fk_flight_airline` FOREIGN KEY (`airline_id`) REFERENCES `airlines` (`airline_id`),
  CONSTRAINT `fk_flight_destination` FOREIGN KEY (`destination_airport_id`) REFERENCES `airports` (`airport_id`),
  CONSTRAINT `fk_flight_gate` FOREIGN KEY (`gate_id`) REFERENCES `gates` (`gate_id`),
  CONSTRAINT `fk_flight_origin` FOREIGN KEY (`origin_airport_id`) REFERENCES `airports` (`airport_id`),
  CONSTRAINT `fk_flight_pilot` FOREIGN KEY (`pilot_id`) REFERENCES `pilots` (`pilot_id`),
  CONSTRAINT `chk_flight_actual_times` CHECK (((`actual_arrival` is null) or (`actual_departure` is null) or (`actual_arrival` >= `actual_departure`))),
  CONSTRAINT `chk_flight_delay` CHECK ((`delay_minutes` >= 0)),
  CONSTRAINT `chk_flight_different_airports` CHECK ((`origin_airport_id` <> `destination_airport_id`)),
  CONSTRAINT `chk_flight_schedule` CHECK ((`scheduled_arrival` > `scheduled_departure`))
) ENGINE=InnoDB AUTO_INCREMENT=6001 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
